package school.magiccodex.paper;
import java.util.*;import java.nio.file.*;import java.util.logging.*;
import org.bukkit.*;import org.bukkit.entity.*;import org.bukkit.plugin.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import net.citizensnpcs.api.CitizensAPI;import net.citizensnpcs.api.npc.*;
class NameplateBridgeTest {
 @TempDir Path temp;
 private MagicCodexBridge plugin(){var p=mock(MagicCodexBridge.class);when(p.getDataFolder()).thenReturn(temp.toFile());when(p.getLogger()).thenReturn(Logger.getAnonymousLogger());return p;}
 @Test void durableCharacterIdentitySurvivesEntityAndCitizensUuidReplacement(){
  var manager=mock(PluginManager.class);when(manager.isPluginEnabled("Citizens")).thenReturn(true);
  var registry=mock(NPCRegistry.class);var citizen=mock(net.citizensnpcs.api.npc.NPC.class);var metadata=mock(MetadataStore.class);when(citizen.data()).thenReturn(metadata);when(citizen.getName()).thenReturn("엘레나");when(citizen.getUniqueId()).thenReturn(UUID.randomUUID());when(metadata.has("chacanpc-id")).thenReturn(true);when(metadata.get("chacanpc-id")).thenReturn("teacher_ellna");
  var first=mock(Player.class);var second=mock(Player.class);when(registry.getNPC(first)).thenReturn(citizen);when(registry.getNPC(second)).thenReturn(citizen);
  try(var b=mockStatic(Bukkit.class);var api=mockStatic(CitizensAPI.class)){b.when(Bukkit::getPluginManager).thenReturn(manager);api.when(CitizensAPI::getNPCRegistry).thenReturn(registry);var bridge=new NameplateBridge(plugin(),false);String key=bridge.npc(first).key();when(citizen.getUniqueId()).thenReturn(UUID.randomUUID());assertEquals(key,bridge.npc(second).key());assertTrue(key.startsWith("character-"));}
 }
 @Test void duplicateNamesReturnCandidateIdsRatherThanChoosingAnNpc()throws Exception{
  var manager=mock(PluginManager.class);when(manager.isPluginEnabled("Citizens")).thenReturn(true);var registry=mock(NPCRegistry.class);var world=mock(World.class);var admin=mock(Player.class);when(admin.getLocation()).thenReturn(new Location(world,0,0,0));
  var one=mock(Player.class);var two=mock(Player.class);when(one.getLocation()).thenReturn(new Location(world,2,0,0));when(two.getLocation()).thenReturn(new Location(world,3,0,0));when(admin.getNearbyEntities(24,24,24)).thenReturn(List.of(one,two));
  for(var entity:List.of(one,two)){var n=mock(net.citizensnpcs.api.npc.NPC.class);when(registry.getNPC(entity)).thenReturn(n);when(n.data()).thenReturn(mock(MetadataStore.class));when(n.getUniqueId()).thenReturn(UUID.randomUUID());when(n.getName()).thenReturn("수위");when(entity.getUniqueId()).thenReturn(UUID.randomUUID());}
  try(var b=mockStatic(Bukkit.class);var api=mockStatic(CitizensAPI.class)){b.when(Bukkit::getPluginManager).thenReturn(manager);api.when(CitizensAPI::getNPCRegistry).thenReturn(registry);var bridge=new NameplateBridge(plugin(),false);var ex=assertThrows(com.mojang.brigadier.exceptions.CommandSyntaxException.class,()->bridge.target(admin,"수위"));assertTrue(ex.getMessage().contains("citizens-"));assertSame(one,bridge.target(admin,"근처").entity());String exact=bridge.npc(two).key();assertSame(two,bridge.target(admin,exact).entity());}
 }
 @Test void rangeBoundaryAndMissingNpcFailClearly(){var manager=mock(PluginManager.class);var admin=mock(Player.class);when(admin.getNearbyEntities(24,24,24)).thenReturn(List.of());try(var b=mockStatic(Bukkit.class)){b.when(Bukkit::getPluginManager).thenReturn(manager);var bridge=new NameplateBridge(plugin(),false);var ex=assertThrows(com.mojang.brigadier.exceptions.CommandSyntaxException.class,()->bridge.target(admin,"근처"));assertTrue(ex.getMessage().contains("24블록"));}}
 @Test void snapshotsIncludeUnassignedAndPendingNicknamesWithoutAccountFallback(){
  var manager=mock(PluginManager.class);var viewer=mock(Player.class);var student=mock(Player.class);var outsider=mock(Player.class);var world=mock(World.class);var origin=new Location(world,0,0,0);
  when(viewer.getLocation()).thenReturn(origin);when(student.getLocation()).thenReturn(new Location(world,2,0,0));when(outsider.getLocation()).thenReturn(new Location(world,3,0,0));
  when(viewer.getNearbyEntities(48,48,48)).thenReturn(List.of(viewer,student,outsider));when(viewer.getListeningPluginChannels()).thenReturn(Set.of(school.magiccodex.protocol.NameplateProtocol.CHANNEL));when(viewer.canSee(student)).thenReturn(true);when(viewer.canSee(outsider)).thenReturn(true);
  when(student.getEntityId()).thenReturn(17);when(student.getUniqueId()).thenReturn(UUID.randomUUID());when(viewer.getEntityId()).thenReturn(16);when(viewer.getUniqueId()).thenReturn(UUID.randomUUID());when(outsider.getEntityId()).thenReturn(18);when(outsider.getUniqueId()).thenReturn(UUID.randomUUID());var plugin=plugin();when(plugin.questHouse(viewer)).thenReturn(-1);when(plugin.questHouse(student)).thenReturn(2);when(plugin.questHouse(outsider)).thenReturn(-1);var names=mock(DisplayNames.class);when(plugin.names()).thenReturn(names);when(names.registered(viewer.getUniqueId())).thenReturn("황준우");when(names.registered(outsider.getUniqueId())).thenReturn("");when(names.registered(student.getUniqueId())).thenReturn("권위닉네임");
  try(var b=mockStatic(Bukkit.class)){b.when(Bukkit::getPluginManager).thenReturn(manager);b.when(Bukkit::getOnlinePlayers).thenReturn(List.of(viewer));var bridge=new NameplateBridge(plugin,false);bridge.push();var bytes=org.mockito.ArgumentCaptor.forClass(byte[].class);verify(viewer).sendPluginMessage(eq(plugin),eq(school.magiccodex.protocol.NameplateProtocol.CHANNEL),bytes.capture());var entries=school.magiccodex.protocol.NameplateProtocol.decode(bytes.getValue());assertEquals(3,entries.size());var row=entries.stream().filter(e->e.uuid().equals(student.getUniqueId())).findFirst().orElseThrow();assertEquals(2,row.style());assertEquals("권위닉네임",row.name());var pending=entries.stream().filter(e->e.uuid().equals(outsider.getUniqueId())).findFirst().orElseThrow();assertEquals(5,pending.style());assertEquals("",pending.name());verify(names,never()).name(any(Player.class));}
 }
 @Test void selfEntryUsesSameAuthorityAndRefreshesHouseNameAndEquippedTitle(){
  var plugin=plugin();var player=mock(Player.class);when(player.getEntityId()).thenReturn(44);when(player.getUniqueId()).thenReturn(UUID.randomUUID());var names=mock(DisplayNames.class);when(plugin.names()).thenReturn(names);when(names.registered(player.getUniqueId())).thenReturn("황준우");var titles=mock(TitleBridge.class);when(plugin.titleService()).thenReturn(titles);when(titles.nameplateTitles(player.getUniqueId())).thenReturn(List.of(NameplateTitlesTest.PREFIX,NameplateTitlesTest.SUFFIX));when(plugin.questHouse(player)).thenReturn(1);var bridge=new NameplateBridge(plugin,false);var first=bridge.playerEntry(player);assertEquals(1,first.style());assertEquals("황준우",first.name());assertTrue(first.titles().stream().allMatch(t->t.color()==NameplateTitlesTest.SUFFIX.color()));
  when(plugin.questHouse(player)).thenReturn(3);when(names.registered(player.getUniqueId())).thenReturn("새이름");when(titles.nameplateTitles(player.getUniqueId())).thenReturn(List.of(NameplateTitlesTest.PREFIX));var updated=bridge.playerEntry(player);assertEquals(3,updated.style());assertEquals("새이름",updated.name());assertEquals(NameplateTitlesTest.PREFIX.color(),updated.titles().getFirst().color());when(plugin.questHouse(player)).thenReturn(-1);assertEquals(5,bridge.playerEntry(player).style());
 }
 @Test void nonAdminIsRejectedBeforeTargetLookup(){var plugin=plugin();var bridge=new NameplateBridge(plugin,false);var player=mock(Player.class);var source=mock(io.papermc.paper.command.brigadier.CommandSourceStack.class);when(source.getSender()).thenReturn(player);com.mojang.brigadier.context.CommandContext<io.papermc.paper.command.brigadier.CommandSourceStack> ctx=mock(com.mojang.brigadier.context.CommandContext.class);when(ctx.getSource()).thenReturn(source);var ex=assertThrows(com.mojang.brigadier.exceptions.CommandSyntaxException.class,()->bridge.run(ctx,"설정"));assertTrue(ex.getMessage().contains("권한"));verify(player,never()).getNearbyEntities(anyDouble(),anyDouble(),anyDouble());}
 @Test void genericNpcUsesDurablePdcIdentityAfterUuidChanges(){var plugin=plugin();when(plugin.getName()).thenReturn("MagicCodexBridge");var manager=mock(PluginManager.class);var entity=mock(Villager.class);var pdc=mock(org.bukkit.persistence.PersistentDataContainer.class);when(entity.getPersistentDataContainer()).thenReturn(pdc);when(entity.getScoreboardTags()).thenReturn(Set.of("magiccodex_npc"));when(entity.getUniqueId()).thenReturn(UUID.randomUUID());when(entity.getName()).thenReturn("도서관사서");try(var b=mockStatic(Bukkit.class)){b.when(Bukkit::getPluginManager).thenReturn(manager);var bridge=new NameplateBridge(plugin,false);String key=bridge.npc(entity).key();var ns=new NamespacedKey(plugin,"nameplate_id");verify(pdc).set(eq(ns),eq(org.bukkit.persistence.PersistentDataType.STRING),eq(key.substring(7)));when(pdc.get(ns,org.bukkit.persistence.PersistentDataType.STRING)).thenReturn(key.substring(7));when(entity.getUniqueId()).thenReturn(UUID.randomUUID());assertEquals(key,bridge.npc(entity).key());}}
}
